///  Mission Design Solution Set — a set of candidate trajectories produced by
///  solving a mission design broad search, typically a Pareto front over
///  competing objectives (total delta-V against total flight time).
///
///  SDS had no multi-candidate container of any kind before this record. The
///  closest existing carrier for a single planned burn is OCM.Maneuver, whose
///  payload is untyped DATA:[string] with MAN_UNITS:[string] and which has no
///  v-infinity, turn angle, flyby periapsis radius, or C3.
class MDS {
  MDS._(this._bc, this._bcOffset);
  factory MDS(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<MDS> reader = _MDSReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  ///  Stable identifier for this solution set.
  String? get SOLUTION_SET_ID => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 4);
  String? get solutionSetId => SOLUTION_SET_ID;
  ///  PROBLEM_ID of the $MDP this set solves. A solution set whose problem
  ///  definition is unknown is not reproducible.
  String? get PROBLEM_ID => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 6);
  String? get problemId => PROBLEM_ID;
  ///  Objectives the front is expressed over, e.g.
  ///  ["TOTAL_DELTA_V_KM_S", "TOTAL_FLIGHT_TIME_DAYS"]. Names MUST be field
  ///  names of MDSCandidate.
  List<String>? get OBJECTIVES => const fb.ListReader<String>(fb.StringReader()).vTableGetNullable(_bc, _bcOffset, 8);
  ///  The candidates.
  List<MDSCandidate>? get CANDIDATES => const fb.ListReader<MDSCandidate>(MDSCandidate.reader).vTableGetNullable(_bc, _bcOffset, 10);
  ///  Solver identity and version that produced the set.
  String? get SOLVER => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 12);
  String? get SOLVER_VERSION => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 14);
  String? get solverVersion => SOLVER_VERSION;
  ///  Ephemeris source used, e.g. a SPICE kernel set identifier.
  String? get EPHEMERIS_SOURCE => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 16);
  String? get ephemerisSource => EPHEMERIS_SOURCE;
  ///  When the set was generated, ISO 8601.
  String? get CREATION_DATE => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 18);
  String? get creationDate => CREATION_DATE;
  ///  Free-form notes.
  String? get COMMENT => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 20);

  @override
  String toString() {
    return 'MDS{solutionSetId: ${solutionSetId}, problemId: ${problemId}, OBJECTIVES: ${OBJECTIVES}, CANDIDATES: ${CANDIDATES}, SOLVER: ${SOLVER}, solverVersion: ${solverVersion}, ephemerisSource: ${ephemerisSource}, creationDate: ${creationDate}, COMMENT: ${COMMENT}}';
  }
}

